import {NextResponse} from "next/server";
import {query} from "@/lib/db";
import {getSession} from "@/lib/auth";
export async function GET(){const r=await query(`SELECT id,title,slug,description,thumbnail_key,price,is_free,is_published FROM courses WHERE is_published=true ORDER BY created_at DESC`);return NextResponse.json({success:true,courses:r.rows})}
export async function POST(req:Request){const s=await getSession();if(!s||s.role!=="admin")return NextResponse.json({error:"Admin access required"},{status:403});const content=req.headers.get("content-type")||"";const b=content.includes("application/json")?await req.json():Object.fromEntries(await req.formData());const title=String(b.title||"").trim(),slug=String(b.slug||"").trim(),description=String(b.description||"").trim();if(!title||!slug)return NextResponse.json({error:"title and slug required"},{status:400});const price=Number(b.price||0),isPublished=String(b.isPublished||"false")==="true";const r=await query(`INSERT INTO courses(title,slug,description,price,is_free,is_published) VALUES($1,$2,$3,$4,$5,$6) RETURNING *`,[title,slug,description||null,price,price===0,isPublished]);if(content.includes("application/json"))return NextResponse.json({success:true,course:r.rows[0]},{status:201});return NextResponse.redirect(new URL("/admin/courses",req.url),303)}
